#[path = "../build_support.rs"]
mod build_support;

use std::{
    fs,
    time::{SystemTime, UNIX_EPOCH},
};

static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
const BUILD_RS: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/build.rs"));
const NATIVE_CMAKELISTS: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/native/CMakeLists.txt"));

#[test]
fn manifest_parser_ignores_comments_and_blank_lines() {
    let directives = build_support::parse_cargo_link_directives(
        r#"
        # Generated by CMake.

        cargo:rustc-link-search=native=/tmp/cudf/lib
        cargo:rustc-link-lib=dylib=cudf_rust
        cargo:metadata=cuda-runtime=shared
        "#,
    )
    .unwrap();

    assert_eq!(
        directives,
        vec![
            "cargo:rustc-link-search=native=/tmp/cudf/lib",
            "cargo:rustc-link-lib=dylib=cudf_rust",
            "cargo:metadata=cuda-runtime=shared",
        ]
    );
}

#[test]
fn manifest_parser_rejects_non_cargo_lines() {
    let error = build_support::parse_cargo_link_directives(
        r#"
        cargo:rustc-link-lib=dylib=cudf_rust
        libcudf.so
        "#,
    )
    .unwrap_err();

    assert!(error.contains("line 3"), "unexpected error: {error}");
}

#[test]
fn read_cargo_link_directives_uses_expected_install_location() {
    let unique = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
    let install_prefix = std::env::temp_dir().join(format!("cudf-sys-build-link-contract-{unique}"));
    let manifest_path = build_support::cargo_link_manifest_path(&install_prefix);
    fs::create_dir_all(manifest_path.parent().unwrap()).unwrap();
    fs::write(&manifest_path, "cargo:rustc-link-search=native=/tmp/cudf/lib\ncargo:rustc-link-lib=dylib=cudf_rust\n")
        .unwrap();

    let directives = build_support::read_cargo_link_directives(&install_prefix).unwrap();

    assert_eq!(
        directives,
        vec!["cargo:rustc-link-search=native=/tmp/cudf/lib", "cargo:rustc-link-lib=dylib=cudf_rust",]
    );

    fs::remove_file(&manifest_path).unwrap();
    fs::remove_dir_all(&install_prefix).unwrap();
}

#[test]
fn parse_cmake_bool_normalizes_common_truthy_and_falsey_values() {
    for truthy in ["1", "on", "TRUE", "Yes"] {
        assert_eq!(build_support::parse_cmake_bool("CUDA_STATIC_RUNTIME", truthy).unwrap(), "ON");
    }

    for falsey in ["0", "off", "FALSE", "No"] {
        assert_eq!(build_support::parse_cmake_bool("CUDA_STATIC_RUNTIME", falsey).unwrap(), "OFF");
    }
}

#[test]
fn parse_cmake_bool_rejects_invalid_values() {
    let error = build_support::parse_cmake_bool("CUDA_STATIC_RUNTIME", "maybe").unwrap_err();
    assert!(error.contains("CUDA_STATIC_RUNTIME"), "unexpected error: {error}");
}

#[test]
fn normalized_cmake_bool_from_env_reads_optional_env_input() {
    let _guard = ENV_LOCK.lock().unwrap();
    std::env::remove_var("CUDA_STATIC_RUNTIME");
    assert_eq!(build_support::normalized_cmake_bool_from_env("CUDA_STATIC_RUNTIME").unwrap(), None);

    std::env::set_var("CUDA_STATIC_RUNTIME", "yes");
    assert_eq!(build_support::normalized_cmake_bool_from_env("CUDA_STATIC_RUNTIME").unwrap(), Some("ON"));

    std::env::remove_var("CUDA_STATIC_RUNTIME");
}

#[test]
fn supported_target_os_accepts_linux_only() {
    build_support::ensure_supported_target_os("linux").expect("linux target should be accepted");

    let error = build_support::ensure_supported_target_os("macos").unwrap_err();
    assert!(error.contains("Linux only"), "unexpected error: {error}");
    assert!(error.contains("macos"), "unexpected error: {error}");

    let error = build_support::ensure_supported_target_os("windows").unwrap_err();
    assert!(error.contains("Linux only"), "unexpected error: {error}");
    assert!(error.contains("windows"), "unexpected error: {error}");
}

#[test]
fn build_script_tracks_build_support_and_cargo_link_template_changes() {
    for tracked in ["build_support.rs", "native/cmake/cargo-link.txt.in"] {
        let expected = format!("cargo:rerun-if-changed={tracked}");
        assert!(BUILD_RS.contains(&expected), "expected build.rs to track {tracked} with `{expected}`");
    }
}

#[test]
fn build_script_checks_target_os_before_configuring_cmake() {
    assert!(
        BUILD_RS.contains("CARGO_CFG_TARGET_OS"),
        "expected build.rs to read the Cargo target OS before configuring the native build"
    );
    assert!(
        BUILD_RS.contains("ensure_supported_target_os"),
        "expected build.rs to enforce the Linux-only target policy"
    );
}

#[test]
fn native_cmakelists_sanitizes_missing_imported_target_properties() {
    for property in ["CUDF_CXX_FLAGS", "CUDF_CUDA_FLAGS", "CUDF_CXX_DEFINITIONS", "CUDF_CUDA_DEFINITIONS"] {
        let sentinel = format!("\"{property}-NOTFOUND\"");
        assert!(
            NATIVE_CMAKELISTS.contains(&sentinel),
            "expected native/CMakeLists.txt to guard imported property {property} against -NOTFOUND"
        );
    }
}

#[test]
fn native_cmakelists_preserves_existing_prefix_path_when_using_install_dir() {
    let required_snippet = "list(PREPEND CMAKE_PREFIX_PATH";
    assert!(
        NATIVE_CMAKELISTS.contains(required_snippet),
        "expected native/CMakeLists.txt to prepend CUDF install paths instead of overwriting CMAKE_PREFIX_PATH"
    );
}
